from typing import Sequence

def products(bases: Sequence[int]) -> list[int]:
    out = [1]
    for b in bases:
        out.append(out[-1] * b)
    return out

def digits(n: int, bases: Sequence[int]) -> list[int]:
    ps = products(bases)
    return [(0 if ps[i] == 0 else n // ps[i]) if b == 0 else (0 if ps[i] == 0 else n // ps[i]) % b for i, b in enumerate(bases)]

def value(ds: Sequence[int], bases: Sequence[int]) -> int:
    return sum(d * p for d, p in zip(ds, products(bases)))

bases = [10, 6, 4, 5]
n = 731
ds = digits(n, bases)
print(ds, value(ds, bases), n % products(bases)[-1])
for k in range(1, len(bases) + 1):
    print(k, ds[:k], n % products(bases)[k])

from math import factorial

def factoradic(n: int, length: int) -> list[int]:
    return [(n // factorial(i)) % (i + 1) for i in range(length)]

def reconstruct(ds: list[int]) -> int:
    return sum(d * factorial(i) for i, d in enumerate(ds))

n = 83
ds = factoradic(n, 5)
print("digits:", ds)
print("reconstructed:", reconstruct(ds))
assert reconstruct(ds) == n

