from typing import Sequence

def reconstruct(digits: Sequence[int], bases: Sequence[int]) -> int:
    if len(digits) > len(bases):
        raise ValueError("insufficient bases")
    place, total = 1, 0
    for digit, base in zip(digits, bases):
        if digit < 0 or base < 0:
            raise ValueError("natural-number inputs required")
        total += digit * place
        place *= base
    return total

from typing import Sequence

def add_and_normalize(a: Sequence[int], b: Sequence[int], bases: Sequence[int]) -> tuple[list[int], int]:
    if not (len(a) == len(b) <= len(bases)):
        raise ValueError("incompatible lengths")
    carry = 0
    out: list[int] = []
    for x, y, base in zip(a, b, bases):
        if base <= 0:
            raise ValueError("positive bases required")
        total = x + y + carry
        out.append(total % base)
        carry = total // base
    return out, carry

